import csv
import io
import re
from typing import List, Dict, Any


def _looks_like_data_start(value: str) -> bool:
    value = value.strip().lstrip("\ufeff")
    return bool(re.match(r"^\d{1,4}[/-]\d{1,2}[/-]\d{1,4}(?:$|[ T])", value))


def _looks_like_header(record: List[str], width: int) -> bool:
    if not record:
        return False
    if _looks_like_data_start(record[0]):
        return False
    if len(record) != width:
        return False
    textual = sum(1 for value in record if re.search(r"[A-Za-z]", value or ""))
    urls = sum(1 for value in record if re.search(r"https?://|www\.", value or "", re.I))
    return textual >= max(2, width // 3) and urls == 0


def _normalize_record(record: List[str], width: int) -> List[str]:
    values = list(record)

    if len(values) < width:
        return values + [""] * (width - len(values))

    if len(values) == width:
        return values

    url_index = None
    for index in range(5, len(values)):
        if re.search(r"https?://|www\.", values[index] or "", re.I):
            url_index = index
            break

    if url_index is not None and url_index >= 7:
        prefix = values[:5]
        name = values[5] if len(values) > 5 else ""
        description = ",".join(values[6:url_index])
        rebuilt = prefix + [name, description] + values[url_index:]
    else:
        rebuilt = values[:width - 1] + [",".join(values[width - 1:])]

    if len(rebuilt) < width:
        rebuilt.extend([""] * (width - len(rebuilt)))
    return rebuilt[:width]


def parse_csv(raw_csv: str):
    width = 9
    source = raw_csv.lstrip("\ufeff")

    try:
        reader = csv.reader(
            io.StringIO(source, newline=""),
            delimiter=",",
            quotechar='"',
            doublequote=True,
            strict=False
        )
        records = [list(record) for record in reader]
    except csv.Error:
        records = []

    nonempty = [(index, record) for index, record in enumerate(records) if record]
    if not nonempty:
        return {
            "columns": ["column_{}".format(index + 1) for index in range(width)],
            "rows": []
        }

    first_data_index = None
    for index, record in nonempty:
        if _looks_like_data_start(record[0] if record else ""):
            first_data_index = index
            break

    header_index = None
    if first_data_index is not None:
        prior = [
            (index, record)
            for index, record in nonempty
            if index < first_data_index
        ]
        for index, record in reversed(prior):
            if _looks_like_header(record, width):
                header_index = index
                break
    else:
        for index, record in nonempty:
            if _looks_like_header(record, width):
                header_index = index
                break

    if header_index is not None:
        columns = _normalize_record(records[header_index], width)
        start_index = header_index + 1
        if first_data_index is not None and first_data_index > start_index:
            start_index = first_data_index
    else:
        columns = ["column_{}".format(index + 1) for index in range(width)]
        start_index = 0

    rows = []
    for index in range(start_index, len(records)):
        record = records[index]
        if not record:
            continue
        rows.append(_normalize_record(record, width))

    return {"columns": columns, "rows": rows}
